%macro get_edgar_full(begyear=1993,endyear=2013);
options nonotes nomprint nomlogic;
%do year=&begyear. %to &endyear.;
	%do qtr=1 %to 4;
		filename edgar url "https://www.sec.gov/Archives/edgar/full-index/&year./QTR&qtr./company.idx";

		data _temp;
			infile edgar firstobs=11 dsd dlm='a7'x expandtabs; 
				%* The data starts in line 11. prior to line 11, the file contains header information.;
				%* the expandtabs and dlm='a7'x options ensure that the entire line is read;
			length line $32767. coname $62. formtype $12. filename $52.;
			input line;
			coname=substr(line,1,62);
			formtype=substr(line,63,12);
			cik=input(substr(line,75,12),best12.);
			date=input(substr(line,87,12),yymmdd10.);
			filename=substr(line,99,52);
			format date DATE9.;
			drop line;
		run;

		proc append base=Edgar_Filings_&begyear.to&endyear. data=_temp; run;
		%put Year=&year. QTR=&qtr.;
	%end;
%end;

options notes;

%mend get_edgar_full;

