** Bring in hand collected sentences to get MGR_NG_EPS value **;

* Compare statistics from two hand collection versions;
proc sql;
create table hc_sentences as
select distinct a.filename from koolaid.hc_sent a
	union corr
select distinct b.filename from koolaid.hc_sent_v2 b
	union corr 
select distinct c.filename from koolaid.hc_sent_v3 c
	union corr 
select distinct d.filename from koolaid.hc_sent_BOTH_v2 d;

create table hc_sentences as
select distinct a.*, b.mgr_ng_eps as mgr_ng_eps_v1, c.mgr_ng_eps as mgr_ng_eps_v2, d.mgr_ng_eps as mgr_ng_eps_v3, e.mgr_ng_eps as mgr_ng_eps_both_v2, 
		max(b.multiple,c.multiple,d.multiple,e.multiple) as multiple
	from hc_sentences a left join koolaid.hc_sent b
			on a.filename=b.filename
		left join koolaid.hc_sent_v2 c
			on a.filename=c.filename
		left join koolaid.hc_sent_v3 d
			on a.filename=d.filename
		left join koolaid.hc_sent_BOTH_v2 e
			on a.filename=e.filename
	group by a.filename;

create table hc_sentences_gaaponly as
select distinct a.filename, max(b.gaap_only,c.gaap_only,d.gaap_only,e.gaap_only) as gaap_only
	from hc_sentences a left join koolaid.hc_sent b
			on a.filename=b.filename
		left join koolaid.hc_sent_v2 c
			on a.filename=c.filename
		left join koolaid.hc_sent_v3 d
			on a.filename=d.filename
		left join koolaid.hc_sent_BOTH_v2 e
			on a.filename=e.filename;
quit;

data hc_sentences;
	set hc_sentences;
	if mgr_ng_eps_both_v2^=. then MGR_NG_EPS=mgr_ng_eps_both_v2;
	if mgr_ng_eps_v3^=. then MGR_NG_EPS=mgr_ng_eps_v3;
	else if mgr_ng_eps_v2^=. then MGR_NG_EPS=mgr_ng_eps_v2;
	else if mgr_ng_eps_v1^=. then MGR_NG_EPS=mgr_ng_eps_v1;

	if mgr_ng_eps^=. then HCed_NG=1; else HCed_NG=0;
run;

